// DejaVu Sans, subconjunto latino. Licença em FONT-LICENSE.txt.
const fonte = "";

export function configurarFonteRecibo(doc) {
  doc.addFileToVFS("DejaVuSans-Recibo.ttf", fonte);
  doc.addFont("DejaVuSans-Recibo.ttf", "ReciboSans", "normal");
  doc.setFont("ReciboSans", "normal");
  doc.setCharSpace(0);
}
